WITH valid AS (SELECT *, LENGTH(carrier) AS carrier_length FROM shipments WHERE carrier IS NOT NULL), joined AS (SELECT src.*, d.order_date, d.discount FROM valid src INNER JOIN orders d ON src.order_id = d.id), enriched AS (SELECT *, MAX(carrier_length) OVER (PARTITION BY status, carrier ORDER BY cost, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_max_carrier_length, SUM(carrier_length) OVER (PARTITION BY status, carrier ORDER BY cost, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_sum_carrier_length, MIN(carrier_length) OVER (PARTITION BY status, carrier ORDER BY cost, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_min_carrier_length FROM joined), joined_shipments AS (SELECT s.id, s.order_id, s.carrier, s.delivered_date, s.order_date, s.discount, s.last4_sum_carrier_length, b.status AS order_status, b.shipping_fee, b.order_date AS order_order_date FROM enriched s LEFT JOIN orders b ON s.order_id = b.id WHERE b.amount > 1350) SELECT id, order_id, carrier, last4_sum_carrier_length, order_status, CASE WHEN carrier RLIKE '^(DHL|FedEx)$' THEN 'GROUP_A' WHEN carrier RLIKE '^(Kerry|Flash)$' THEN 'GROUP_B' ELSE 'CORE' END AS carrier_zone FROM joined_shipments;
